-- 托福词库 batch1:freq_rank 前 4471 词
-- 生成: node scripts/vocab/ingest-toefl.mjs --emit-sql
-- 数据源: skywind3000/ECDICT · MIT License (c) 2025 Linwei
-- ⚠️ 由 Aaron 执行。脚本本身从不写库。
--
-- 幂等性: vocab_words 走 ON CONFLICT (lower(headword))(索引 vocab_words_headword_uq),
--         vocab_word_banks 走 PK (word_id, bank_id)。重复跑不会产生重复行。
-- bank_id 用子查询取,不硬编码 uuid。

BEGIN;

-- ── 跑之前的基线 ──
SELECT 'BEFORE' AS stage,
       (SELECT count(*) FROM vocab_words) AS words,
       (SELECT count(*) FROM vocab_word_banks
         WHERE bank_id = (SELECT id FROM vocab_banks WHERE code = 'toefl')) AS toefl_links;

-- ① 词条
ON CONFLICT (lower(headword)) DO UPDATE
  SET pos        = COALESCE(EXCLUDED.pos, vocab_words.pos),
      freq_rank  = COALESCE(EXCLUDED.freq_rank, vocab_words.freq_rank),
      updated_at = now();

-- ② 挂到 toefl 词库
SELECT w.id, b.id
  FROM vocab_words w
  CROSS JOIN (SELECT id FROM vocab_banks WHERE code = 'toefl') b
 WHERE lower(w.headword) IN ('defense', 'attorney', 'participant', 'concerned', 'involved', 'neighbor', 'context', 'voter', 'grab', 'theater', 'regional', 'currently', 'ethnic', 'landscape', 'regime', 'perception', 'opposition', 'coverage', 'intervention', 'cite', 'sector', 'honor', 'asset', 'proceeding', 'funding', 'therapy', 'remaining', 'chip', 'transition', 'coalition', 'negotiation', 'congressional', 'championship', 'deficit', 'ally', 'confront', 'peer', 'retirement', 'literally', 'administrator', 'constantly', 'diversity', 'dealer', 'clinical', 'fiber', 'incorporate', 'lawsuit', 'testimony', 'cooperation', 'profile', 'mechanism', 'penalty', 'constitutional', 'infection', 'initially', 'incentive', 'ken', 'elite', 'senator', 'awareness', 'testify', 'founder', 'originally', 'assault', 'violation', 'controversy', 'defensive', 'constitute', 'representation', 'emission', 'entitled', 'vulnerable', 'capability', 'celebrity', 'ongoing', 'counselor', 'survivor', 'psychologist', 'galaxy', 'incredible', 'mall', 'conviction', 'myth', 'standing', 'flavor', 'sue', 'demonstration', 'assert', 'offensive', 'dominant', 'heritage', 'legacy', 'orientation', 'inflation', 'cluster', 'depict', 'sanction', 'habitat', 'ethics', 'odds', 'frustration', 'discourse', 'portray', 'nonetheless', 'recording', 'colonial', 'cognitive', 'fitness', 'dramatically', 'makeup', 'alliance', 'hypothesis', 'norm', 'counseling', 'ritual', 'counsel', 'presidency', 'subtle', 'integrity', 'essence', 'pitcher', 'rumor', 'humanity', 'administrative', 'allegation', 'initiate', 'plead', 'seemingly', 'effectiveness', 'inspector', 'fraud', 'contend', 'array', 'hallway', 'monster', 'facilitate', 'rip', 'recession', 'supervisor', 'arena', 'diagnosis', 'consistently', 'warrior', 'prediction', 'graphics', 'domain', 'weird', 'ideology', 'chronic', 'innovation', 'administer', 'simultaneously', 'trigger', 'amendment', 'adoption', 'convict', 'indigenous', 'undermine', 'traditionally', 'ballot', 'rhetoric', 'convinced', 'm